        public static XgStageQuiz Quiz(string id) { foreach(var q in Quizzes)if(q.id==id)return q;return null; }
        static XgLessonDefinition L(string id,int stage,string title,string titleEn,string saw,string sawEn,string body,string bodyEn,string voice="",string voiceEn="") => new XgLessonDefinition{id=id,stage=stage,title=title,titleEn=titleEn,saw=saw,sawEn=sawEn,body=body,bodyEn=bodyEn,voice=voice,voiceEn=voiceEn};
