        public static XgLessonDefinition Card(string id) { foreach(var c in Cards)if(c.id==id)return c;return null; }
        public static string QuizNode(XgStageQuiz q) { if(!string.IsNullOrEmpty(q.node))return q.node;return q.trigger=="gap"?"train.holdout":q.stage==3?"lenet":q.stage>=6?"sft":"train.curve"; }
        public static void AddAtlas(List<XgNode> nodes)
        {
            foreach(var c in Cards)nodes.Add(new XgNode{id="lesson."+c.id,tree="atlas",lane="atlas",kind=XgNodeKind.Phenomenon,target="lesson."+c.id,stage=c.stage,name=c.title,nameEn=c.titleEn,note=c.saw+"\n"+c.body,noteEn=c.sawEn+"\n"+c.bodyEn});
            foreach(var q in Quizzes)nodes.Add(new XgNode{id="quiz."+q.id,tree="atlas",lane="atlas",kind=XgNodeKind.Phenomenon,target="quiz."+q.id,stage=q.stage,name=q.q,nameEn=q.qEn,note=q.explain,noteEn=q.explainEn});
        }
    }
